/**
 * Sprite sheets for the canvas renderer. Presentation-side (touches the DOM
 * Image API), kept out of the pure simulation like renderer.ts.
 *
 * Everything standing in the world is a voxel-baked sheet generated by
 * `tools/bake-voxels.mjs` (plane, canopy, diver, props, balloons, clouds),
 * rendered at the yaw/elevation steps the Mode 7 camera needs; their layout
 * lives in the generated `baked-sprites.ts`. They're optional everywhere: the
 * renderer draws stand-ins until they load (or forever if loading fails). The
 * sky, the sun and the hills are painted procedurally (horizon.ts).
 */
import { BAKED_SPECS, type BakedName } from './baked-sprites';

/** A voxel-baked sheet: its image plus the generated layout. */
export type BakedSheet = (typeof BAKED_SPECS)[BakedName] & { image: CanvasImageSource };
export type BakedAtlas = Record<BakedName, BakedSheet>;

async function loadImage(src: string): Promise<HTMLImageElement> {
  const image = new Image();
  image.src = src;
  await image.decode();
  return image;
}

// Loaded once per page and shared by the game and the menus' backdrops.
let bakedPromise: Promise<BakedAtlas> | null = null;

/** Load every voxel-baked sheet (memoised). */
export function loadBaked(): Promise<BakedAtlas> {
  bakedPromise ??= fetchBaked().catch((e: unknown) => {
    bakedPromise = null;
    throw e;
  });
  return bakedPromise;
}

async function fetchBaked(basePath = 'assets/sprites/baked'): Promise<BakedAtlas> {
  const entries = await Promise.all(
    (Object.keys(BAKED_SPECS) as BakedName[]).map(
      async (name) =>
        [
          name,
          { image: await loadImage(`${basePath}/${name}.png`), ...BAKED_SPECS[name] },
        ] as const,
    ),
  );
  return Object.fromEntries(entries) as BakedAtlas;
}

/**
 * Frame index in a baked sheet for a view: the row rendered nearest to the
 * camera `elevation` (rad), the yaw step nearest to `relYaw` (the object's
 * heading minus the camera's, rad), and an animation/variant column.
 */
export function bakedFrame(
  spec: { cols: number; yaws: number; anim: number; elevs: readonly number[] },
  elevation: number,
  relYaw = 0,
  anim = 0,
): number {
  const deg = (elevation * 180) / Math.PI;
  let e = 0;
  for (let i = 1; i < spec.elevs.length; i++) {
    if (Math.abs(spec.elevs[i] - deg) < Math.abs(spec.elevs[e] - deg)) {
      e = i;
    }
  }
  const step = (Math.PI * 2) / spec.yaws;
  const y = spec.yaws > 1 ? ((Math.round(relYaw / step) % spec.yaws) + spec.yaws) % spec.yaws : 0;
  const a = ((Math.floor(anim) % spec.anim) + spec.anim) % spec.anim;
  return e * spec.cols + y * spec.anim + a;
}

/**
 * Draw a baked frame with its anchor (the model origin) at (x, y), scaled by
 * `scale` (screen pixels per sheet pixel), optionally rotated about the anchor.
 * Far, shrunken sprites are smoothed (a cheap mip) so they don't sparkle.
 */
export function drawBaked(
  ctx: CanvasRenderingContext2D,
  sheet: BakedSheet,
  frame: number,
  x: number,
  y: number,
  scale: number,
  rotation = 0,
): void {
  const dw = Math.max(1, Math.round(sheet.fw * scale));
  const dh = Math.max(1, Math.round(sheet.fh * scale));
  const sx = frame * sheet.fw;
  ctx.imageSmoothingEnabled = scale < 0.6;
  if (rotation !== 0) {
    ctx.save();
    ctx.translate(Math.round(x), Math.round(y));
    ctx.rotate(rotation);
    ctx.drawImage(
      sheet.image,
      sx,
      0,
      sheet.fw,
      sheet.fh,
      -Math.round(sheet.ax * scale),
      -Math.round(sheet.ay * scale),
      dw,
      dh,
    );
    ctx.restore();
  } else {
    ctx.drawImage(
      sheet.image,
      sx,
      0,
      sheet.fw,
      sheet.fh,
      Math.round(x - sheet.ax * scale),
      Math.round(y - sheet.ay * scale),
      dw,
      dh,
    );
  }
  ctx.imageSmoothingEnabled = false;
}
